1	type Customer = { yearsWithMHPCO: number };
2	type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
3	type Step = { op: "quote"; items: Item[] };
4	type Scenario = { customer: Customer; steps: Step[] };
5	
6	type QuoteResult = { premium: number };
7	type ScenarioResult = { results: QuoteResult[] };
8	
9	const PROCESSING_FEE = 5;
10	const FIRST_INSURANCE_PCT = 0.10;
11	const CURSE_PCT = 0.50;
12	const HIGH_ENCH_PCT = 0.30;
13	const HIGH_ENCH_THRESHOLD = 5;
14	const FLOAT_TOLERANCE = 1e-9;
15	const BLOCK_SIZE = 3;
16	const BLOCK_PREMIUM = 60;
17	
18	const BASE_PREMIUM: Record<string, number> = {
19	  sword: 100,
20	  amulet: 60,
21	  staff: 80,
22	  potion: 40,
23	  rune: 25,
24	  moonstone: 25,
25	};
26	
27	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
28	
29	const isComponentType = (type: string): boolean => COMPONENT_TYPES.has(type);
30	
31	const roundUp = (n: number): number => Math.ceil(n - FLOAT_TOLERANCE);
32	
33	const countByType = (items: Item[]): Map<string, number> => {
34	  const counts = new Map<string, number>();
35	  for (const item of items) {
36	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
37	  }
38	  return counts;
39	};
40	
41	const groupBasePremium = (type: string, count: number): number =>
42	  isComponentType(type) && count === BLOCK_SIZE
43	    ? BLOCK_PREMIUM
44	    : count * BASE_PREMIUM[type];
45	
46	const sumBasePremiums = (items: Item[]): number => {
47	  let total = 0;
48	  for (const [type, count] of countByType(items)) {
49	    total += groupBasePremium(type, count);
50	  }
51	  return total;
52	};
53	
54	const itemSurchargePct = (item: Item): number =>
55	  (item.cursed ? CURSE_PCT : 0) +
56	  ((item.enchantment ?? 0) >= HIGH_ENCH_THRESHOLD ? HIGH_ENCH_PCT : 0);
57	
58	const itemSurcharge = (item: Item): number =>
59	  BASE_PREMIUM[item.type] * itemSurchargePct(item);
60	
61	const itemSurcharges = (items: Item[]): number =>
62	  items.reduce((total, item) => total + itemSurcharge(item), 0);
63	
64	const computeQuotePremium = (items: Item[]): number => {
65	  const policyBase = sumBasePremiums(items);
66	  const surcharges = itemSurcharges(items);
67	  const firstIns = policyBase * FIRST_INSURANCE_PCT;
68	  return roundUp(policyBase + surcharges + firstIns + PROCESSING_FEE);
69	};
70	
71	export const runScenario = (scenario: Scenario): ScenarioResult => ({
72	  results: scenario.steps.map((step) => ({ premium: computeQuotePremium(step.items) })),
73	});
